// Public Screenscape embed defaults. These are not secrets — the browser already
// receives the embed URLs from /config.js. Keeping them in client code means the
// player still works on static hosts (GitHub Pages) where /config.js is not
// generated by server.mjs.
export const DEFAULT_MOVIE_EMBED_TEMPLATE =
  'https://web.screenscape.fun/embed?tmdb={tmdbId}&type=movie&lan=eng';

export const DEFAULT_TV_EMBED_TEMPLATE =
  'https://web.screenscape.fun/embed?tmdb={tmdbId}&type=tv&s={s}&e={e}&lan=eng';
